def tree_from(levels):
    # [7, 4, 9, 2, 6, None, 3]: level by level, left to right, None for a missing child (a missing node has no children listed)
    nodes = [None if v is None else TreeNode(v) for v in levels]
    children = iter(nodes[1:])
    for node in nodes:
        if node is not None:
            node.left = next(children, None)
            node.right = next(children, None)
    return nodes[0] if nodes else None
def leaning_left(n):
    # a tree that is one path of n nodes, every value 1
    levels = [1]
    for _ in range(n - 1):
        levels += [1, None]
    return tree_from(levels)

